--       factory interfaces, the wl_callback interface is frozen at version 1.
data WlCallback

-- | Interface metadata for @wl_callback@.
wlCallbackInterface :: Binding.Interface WlCallback
wlCallbackInterface = Binding.Interface "wl_callback" 1

-- | Events emitted by @wl_callback@.
data WlCallbackEvent fd
