-- | destroy wl_compositor
--
-- This request destroys the wl_compositor. This has no effect on any other objects.
encodeWlCompositorRelease :: Binding.RequestEncoder fd
encodeWlCompositorRelease =
  Binding.RequestEncoder (Wire.Opcode 2) 7 True (pure ())

-- | a shared memory pool
--
-- The wl_shm_pool object encapsulates a piece of memory shared
--       between the compositor and client.  Through the wl_shm_pool
--       object, the client can allocate shared memory wl_buffer objects.
--       All objects created through the same pool share the same
--       underlying mapped memory. Reusing the mapped memory avoids the
--       setup/teardown overhead and is useful when interactively resizing
--       a surface or for many small buffers.
data WlShmPool

-- | Interface metadata for @wl_shm_pool@.
wlShmPoolInterface :: Binding.Interface WlShmPool
wlShmPoolInterface = Binding.Interface "wl_shm_pool" 2

-- | create a buffer from the pool
--
-- Create a wl_buffer object from the pool.
--
--         The buffer is created offset bytes into the pool and has
--         width and height as specified.  The stride argument specifies
--         the number of bytes from the beginning of one row to the beginning
--         of the next.  The format is the pixel format of the buffer and
--         must be one of those advertised through the wl_shm.format event.
--
--         A buffer will keep a reference to the pool it was created from
--         so it is valid to destroy the pool immediately after creating
--         a buffer from it.
--
-- @idValue@: buffer to create
-- @offsetValue@: buffer byte offset within the pool
-- @widthValue@: buffer width, in pixels
-- @heightValue@: buffer height, in pixels
-- @strideValue@: number of bytes from the beginning of one row to the beginning of the next row
-- @formatValue@: buffer pixel format
encodeWlShmPoolCreateBuffer :: Wire.ObjectId -> Int32 -> Int32 -> Int32 -> Int32 -> WlShmFormatEnum -> Binding.RequestEncoder fd
encodeWlShmPoolCreateBuffer idValue offsetValue widthValue heightValue strideValue formatValue =
  Binding.RequestEncoder (Wire.Opcode 0) 1 False $ do
    Arguments.putNewId idValue
    Arguments.putInt offsetValue
    Arguments.putInt widthValue
    Arguments.putInt heightValue
    Arguments.putInt strideValue
    Arguments.putUint (wlShmFormatEnumValue formatValue)

-- | destroy the pool
--
-- Destroy the shared memory pool.
--
--         The mmapped memory will be released when all
--         buffers that have been created from this pool
--         are gone.
encodeWlShmPoolDestroy :: Binding.RequestEncoder fd
encodeWlShmPoolDestroy =
  Binding.RequestEncoder (Wire.Opcode 1) 1 True (pure ())

-- | change the size of the pool mapping
--
-- This request will cause the server to remap the backing memory
--         for the pool from the file descriptor passed when the pool was
--         created, but using the new size.  This request can only be
--         used to make the pool bigger.
--
--         This request only changes the amount of bytes that are mmapped
--         by the server and does not touch the file corresponding to the
--         file descriptor passed at creation time. It is the client's
--         responsibility to ensure that the file is at least as big as
--         the new pool size.
--
-- @sizeValue@: new size of the pool, in bytes
encodeWlShmPoolResize :: Int32 -> Binding.RequestEncoder fd
encodeWlShmPoolResize sizeValue =
  Binding.RequestEncoder (Wire.Opcode 2) 1 False $ do
    Arguments.putInt sizeValue

-- | shared memory support
--
-- A singleton global object that provides support for shared
--       memory.
--
--       Clients can create wl_shm_pool objects using the create_pool
--       request.
--
--       On binding the wl_shm object one or more format events
--       are emitted to inform clients about the valid pixel formats
--       that can be used for buffers.
data WlShm

-- | Interface metadata for @wl_shm@.
wlShmInterface :: Binding.Interface WlShm
wlShmInterface = Binding.Interface "wl_shm" 2

-- | create a shm pool
--
-- Create a new wl_shm_pool object.
--
--         The pool can be used to create shared memory based buffer
--         objects.  The server will mmap size bytes of the passed file
--         descriptor, to use as backing memory for the pool.
--
-- @idValue@: pool to create
-- @fdValue@: file descriptor for the pool
-- @sizeValue@: pool size, in bytes
encodeWlShmCreatePool :: Wire.ObjectId -> fd -> Int32 -> Binding.RequestEncoder fd
encodeWlShmCreatePool idValue fdValue sizeValue =
  Binding.RequestEncoder (Wire.Opcode 0) 1 False $ do
    Arguments.putNewId idValue
    Arguments.putFd fdValue
    Arguments.putInt sizeValue

-- | release the shm object
--
-- Using this request a client can tell the server that it is not going to
--         use the shm object anymore.
--
--         Objects created via this interface remain unaffected.
encodeWlShmRelease :: Binding.RequestEncoder fd
encodeWlShmRelease =
  Binding.RequestEncoder (Wire.Opcode 1) 2 True (pure ())

-- | Events emitted by @wl_shm@.
data WlShmEvent fd
  = -- | pixel format description
    --
    -- Informs the client about a valid pixel format that
    --         can be used for buffers. Known formats include
    --         argb8888 and xrgb8888.
    --
    --         Extensions to drm_fourcc.h (or the format enum) do not require
    --         increasing the wl_shm version; as a result, clients may receive format
    --         codes which were not in the list at the time the client was made.
    WlShmFormat
      WlShmFormatEnum
  deriving (Eq, Show)

decodeWlShmEvent :: Wire.Opcode -> Maybe (Binding.EventDecoder fd (WlShmEvent fd))
decodeWlShmEvent (Wire.Opcode 0) =
  Just (Binding.EventDecoder 1 False (WlShmFormat <$> (WlShmFormatEnum <$> Arguments.getUint)))
decodeWlShmEvent _ = Nothing

-- | wl_shm error values
--
-- These errors can be emitted in response to wl_shm requests.
newtype WlShmErrorEnum = WlShmErrorEnum
  { wlShmErrorEnumValue :: Word32
  }
  deriving (Eq, Ord, Show)

-- | buffer format is not known
pattern WlShmErrorEnumInvalidFormat :: WlShmErrorEnum
pattern WlShmErrorEnumInvalidFormat = WlShmErrorEnum 0

-- | invalid size or stride during pool or buffer creation
pattern WlShmErrorEnumInvalidStride :: WlShmErrorEnum
pattern WlShmErrorEnumInvalidStride = WlShmErrorEnum 1

-- | mmapping the file descriptor failed
pattern WlShmErrorEnumInvalidFd :: WlShmErrorEnum
pattern WlShmErrorEnumInvalidFd = WlShmErrorEnum 2

-- | pixel formats
--
-- This describes the memory layout of an individual pixel.
--
--         All renderers should support argb8888 and xrgb8888 but any other
--         formats are optional and may not be supported by the particular
--         renderer in use.
--
--         The drm format codes match the macros defined in drm_fourcc.h, except
--         argb8888 and xrgb8888. The formats actually supported by the compositor
--         will be reported by the format event. See drm_fourcc.h for more detailed
--         format descriptions.
--
--         For all wl_shm formats and unless specified in another protocol
--         extension, pre-multiplied alpha is used for pixel values.
newtype WlShmFormatEnum = WlShmFormatEnum
  { wlShmFormatEnumValue :: Word32
  }
  deriving (Eq, Ord, Show)

