pattern WlPointerAxisSourceEnumFinger = WlPointerAxisSourceEnum 1

-- | continuous coordinate space
pattern WlPointerAxisSourceEnumContinuous :: WlPointerAxisSourceEnum
pattern WlPointerAxisSourceEnumContinuous = WlPointerAxisSourceEnum 2

-- | a physical wheel tilt
