-- | transformation applied to buffer contents
--
-- This describes transformations that clients and compositors apply to
--         buffer contents.
--
--         The flipped values correspond to an initial flip around a
--         vertical axis followed by rotation.
--
--         The purpose is mainly to allow clients to render accordingly and
--         tell the compositor, so that for fullscreen surfaces, the
--         compositor will still be able to scan out directly from client
--         surfaces.
newtype WlOutputTransformEnum = WlOutputTransformEnum
  { wlOutputTransformEnumValue :: Word32
  }
  deriving (Eq, Ord, Show)

-- | no transform
pattern WlOutputTransformEnumNormal :: WlOutputTransformEnum
pattern WlOutputTransformEnumNormal = WlOutputTransformEnum 0

-- | 90 degrees counter-clockwise
pattern WlOutputTransformEnumN90 :: WlOutputTransformEnum
pattern WlOutputTransformEnumN90 = WlOutputTransformEnum 1

-- | 180 degrees counter-clockwise
pattern WlOutputTransformEnumN180 :: WlOutputTransformEnum
pattern WlOutputTransformEnumN180 = WlOutputTransformEnum 2

-- | 270 degrees counter-clockwise
pattern WlOutputTransformEnumN270 :: WlOutputTransformEnum
pattern WlOutputTransformEnumN270 = WlOutputTransformEnum 3

-- | 180 degree flip around a vertical axis
pattern WlOutputTransformEnumFlipped :: WlOutputTransformEnum
pattern WlOutputTransformEnumFlipped = WlOutputTransformEnum 4

-- | flip and rotate 90 degrees counter-clockwise
pattern WlOutputTransformEnumFlippedN90 :: WlOutputTransformEnum
pattern WlOutputTransformEnumFlippedN90 = WlOutputTransformEnum 5

-- | flip and rotate 180 degrees counter-clockwise
pattern WlOutputTransformEnumFlippedN180 :: WlOutputTransformEnum
pattern WlOutputTransformEnumFlippedN180 = WlOutputTransformEnum 6

-- | flip and rotate 270 degrees counter-clockwise
pattern WlOutputTransformEnumFlippedN270 :: WlOutputTransformEnum
pattern WlOutputTransformEnumFlippedN270 = WlOutputTransformEnum 7

