newtype WlOutputModeFlags = WlOutputModeFlags
  { wlOutputModeFlagsValue :: Word32
  }
  deriving (Eq, Ord, Show)

-- | indicates this is the current mode
pattern WlOutputModeFlagsCurrent :: WlOutputModeFlags
pattern WlOutputModeFlagsCurrent = WlOutputModeFlags 1

